use super::*;
#[derive(PartialEq,Eq)]struct Collision(usize);impl Hash for Collision{fn hash<H:Hasher>(&self,h:&mut H){0usize.hash(h)}}
struct L{calls:usize,stop:usize}impl Ledger for L{type Error=();fn work(&mut self,_:usize)->Result<(),()>{self.calls+=1;if self.calls>self.stop{Err(())}else{Ok(())}}fn allocation(&mut self,_:usize)->Result<(),()>{self.work(1)}fn allocation_limit(&mut self){}}
#[test]fn a7_collision_failed_push_reverse_pop_refill(){let mut count=L{calls:0,stop:usize::MAX};let mut entries=Entries::default();for i in 0..80{entries.push(Collision(i),i,1,&mut count).unwrap();}let calls=count.calls;for stop in 0..=calls{let mut ledger=L{calls:0,stop};let mut path=Entries::default();for i in 0..80{if path.push(Collision(i),i,1,&mut ledger).is_err(){break}}while path.pop().is_some(){}assert!(path.buckets.iter().all(|b|*b==NONE));let mut ledger=L{calls:0,stop:usize::MAX};for i in 0..25{path.push(Collision(i),i,1,&mut ledger).unwrap();}for i in 0..25{assert_eq!(path.find(&Collision(i),1,&mut ledger).unwrap(),Some(i));}assert_eq!(path.suffix(20).map(|(_,v)|*v).collect::<Vec<_>>(),(20..25).collect::<Vec<_>>());while path.pop().is_some(){}assert!(path.buckets.iter().all(|b|*b==NONE));}println!("storage-failure-checkpoints={calls}");}
